using FluentValidation;
using Refahi.Modules.CreditPayments.Application.Contracts;
using Refahi.Modules.CreditPayments.Domain;

namespace Refahi.Modules.CreditPayments.Application;

public sealed class CreateMerchantValidator:AbstractValidator<CreateMerchantCommand>{public CreateMerchantValidator(){RuleFor(x=>x.SupplierId).NotEmpty().WithMessage("تامین‌کننده الزامی است");RuleFor(x=>x.DisplayName).MaximumLength(200).WithMessage("نام نمایشی حداکثر ۲۰۰ نویسه است");}}
public sealed class CreateTerminalValidator:AbstractValidator<CreateTerminalCommand>{public CreateTerminalValidator(){RuleFor(x=>x.MerchantId).NotEmpty().WithMessage("پذیرنده الزامی است");RuleFor(x=>x.Name).NotEmpty().MaximumLength(150).WithMessage("نام پایانه نامعتبر است");RuleFor(x=>x.ApprovedCategoryCode).NotEmpty().MaximumLength(100).WithMessage("کد دسته‌بندی نامعتبر است");RuleFor(x=>x.MinPaymentAmountMinor).GreaterThan(0).WithMessage("حداقل مبلغ باید مثبت باشد");RuleFor(x=>x.MaxPaymentAmountMinor).GreaterThanOrEqualTo(x=>x.MinPaymentAmountMinor).WithMessage("حداکثر مبلغ نباید کمتر از حداقل باشد");RuleFor(x=>x.AllowedReturnUrls).NotEmpty().WithMessage("حداقل یک نشانی بازگشت الزامی است");}}
public sealed class UpdateTerminalPolicyValidator:AbstractValidator<UpdateTerminalPolicyCommand>{public UpdateTerminalPolicyValidator(){RuleFor(x=>x.ApprovedCategoryCode).NotEmpty().MaximumLength(100).WithMessage("کد دسته‌بندی نامعتبر است");RuleFor(x=>x.MinPaymentAmountMinor).GreaterThan(0).WithMessage("حداقل مبلغ باید مثبت باشد");RuleFor(x=>x.MaxPaymentAmountMinor).GreaterThanOrEqualTo(x=>x.MinPaymentAmountMinor).WithMessage("حداکثر مبلغ نباید کمتر از حداقل باشد");RuleFor(x=>x.ExpectedVersion).GreaterThan(0).WithMessage("نسخه الزامی است");}}
public sealed class IssueCredentialValidator:AbstractValidator<IssueCredentialCommand>{public IssueCredentialValidator(){RuleFor(x=>x.Label).NotEmpty().MaximumLength(100).WithMessage("برچسب اعتبارنامه نامعتبر است");RuleFor(x=>x.Scopes).NotEmpty().WithMessage("حداقل یک سطح دسترسی الزامی است");RuleForEach(x=>x.Scopes).Must(CredentialScopes.All.Contains).WithMessage("سطح دسترسی ناشناخته است");RuleFor(x=>x.ExpiresAt).GreaterThan(DateTimeOffset.UtcNow).When(x=>x.ExpiresAt.HasValue).WithMessage("تاریخ انقضا باید در آینده باشد");}}
public sealed class ConfigureWebhookValidator:AbstractValidator<ConfigureWebhookCommand>{public ConfigureWebhookValidator(){RuleFor(x=>x.Url).NotEmpty().MaximumLength(2048).WithMessage("نشانی وب‌هوک نامعتبر است");RuleFor(x=>x.ExpectedVersion).GreaterThan(0).WithMessage("نسخه الزامی است");}}
